\label{tab:multiseed}
\begin{tabular}{@{}llccc@{}}
\toprule
Sparsity & Method & Mean Acc.\,(\%) & Std\,(pp) & Seeds \\
\midrule
\multirow{4}{*}{20\%} & CKA-only & 64.39 & 0.19 & 3 \\
